defs: [
  ["Start-up capital", "The finance needed by a new business to pay for essential non-current and current assets before it can begin trading."],
  ["Working capital", "The finance needed by a business to pay its day-to-day costs."],
  ["Capital expenditure", "Money spent on non-current (fixed) assets which will last for more than one year."],
  ["Revenue expenditure", "Money spent on day-to-day expenses which do not involve the purchase of a long-term asset, such as wages or rent."],
  ["Internal finance", "Finance obtained from within the business itself."],
  ["External finance", "Finance obtained from sources outside of and separate from the business."],
  ["Retained profit", "Profit kept in the business after the owners have taken their share."],
  ["Debentures", "Long-term loan certificates issued by limited companies."],
  ["Debt factoring", "Selling the claims on a business's debtors to a specialist agency for immediate cash, at a discount."],
  ["Overdraft", "An arrangement allowing a business to spend more money than is currently in its bank account, up to an agreed limit."],
  ["Trade credit", "Delaying payment to suppliers, which leaves the business in a better cash position in the short term."],
  ["Hire purchase", "Buying a non-current asset by paying a deposit and then monthly instalments that include an interest charge."],
  ["Leasing", "Using an asset in return for regular payments without owning it."],
  ["Micro-finance", "Providing financial services, including very small loans, to poor people not served by traditional banks."],
  ["Crowdfunding", "Funding a project by raising small amounts of money from a large number of people, typically over the internet."],
  ["Gearing", "The proportion of a business's total capital that has been raised from long-term loans."],
  ["Rights issue", "An issue of new shares that gives existing shareholders the right to buy them in proportion to their current holding."]
],
